@dataclass(frozen=True)
class SkuPercentOff:
    skus: frozenset[str]
    percent: int

    def discount(self, order: Order) -> int:
        return sum(apply_rate(l.total_cents, self.percent) for l in order.lines if l.sku in self.skus)
